import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import {
  weakerPyright,
  readPyrightFile,
  resolvePyright,
  stripJsonComments,
  weakerComments,
} from './pyright-config.js';
import { tempRepo } from '../../testing/engine.js';

describe('stripJsonComments', () => {
  it('removes comments and trailing commas, never inside strings', () => {
    const text = [
      '// Generated by Talos.',
      '{',
      '  "extends": "./a//b.json", /* inline */',
      '  "include": ["src", "tests",],',
      '  "note": "a, }",',
      '}',
    ].join('\n');
    expect(JSON.parse(stripJsonComments(text))).toEqual({
      extends: './a//b.json',
      include: ['src', 'tests'],
      note: 'a, }',
    });
  });
});

describe('readPyrightFile', () => {
  it('reads [tool.basedpyright], then [tool.pyright], from a pyproject.toml', () => {
    const both = '[tool.pyright]\nreportAny = false\n[tool.basedpyright]\nreportAny = "error"\n';
    expect(readPyrightFile('pyproject.toml', both)).toEqual({ reportAny: 'error' });
    expect(readPyrightFile('pyproject.toml', '[tool.pyright]\nstrict = ["src"]\n')).toEqual({
      strict: ['src'],
    });
    expect(readPyrightFile('pyproject.toml', '[project]\nname = "x"\n')).toEqual({});
  });

  it('is empty for a file it cannot read', () => {
    expect(readPyrightFile('pyrightconfig.json', '{ broken')).toEqual({});
    expect(readPyrightFile('pyrightconfig.json', '[1, 2]')).toEqual({});
  });
});

describe('resolvePyright', () => {
  it('lays each file over the one it extends', async () => {
    const root = await tempRepo({
      'pyrightconfig.talos.json': '// base\n{ "typeCheckingMode": "all", "venv": ".venv" }\n',
      'pyrightconfig.json': '{ "extends": "./pyrightconfig.talos.json", "reportAny": "none" }',
    });
    expect(await resolvePyright(join(root, 'pyrightconfig.json'))).toEqual({
      typeCheckingMode: 'all',
      venv: '.venv',
      reportAny: 'none',
    });
    expect(await resolvePyright(join(root, 'missing.json'))).toEqual({});
  });
});

describe('weakerPyright', () => {
  it('accepts "all" with every rule left an error', () => {
    expect(
      weakerPyright({
        typeCheckingMode: 'all',
        reportAny: 'error',
        reportUnusedImport: true,
        strictListInference: true,
        enableTypeIgnoreComments: false,
        ignore: [],
        pythonVersion: '3.12',
      }),
    ).toEqual([]);
  });

  it('names a weaker mode, rule, switch or exemption, also per environment', () => {
    const found = weakerPyright({
      typeCheckingMode: 'strict',
      reportAny: 'warning',
      reportUnusedCallResult: false,
      strictListInference: false,
      enableTypeIgnoreComments: true,
      ignore: ['src/legacy'],
      allowedUntypedLibraries: ['requests'],
      executionEnvironments: [{ root: 'tests', reportPrivateUsage: 'none' }],
    });
    expect(found.map((w) => w.message)).toEqual([
      'sets typeCheckingMode to "strict"',
      'sets reportAny to "warning"',
      'sets reportUnusedCallResult to false',
      'sets strictListInference to false',
      'sets enableTypeIgnoreComments to true',
      'sets ignore to ["src/legacy"]',
      'sets allowedUntypedLibraries to ["requests"]',
      'sets executionEnvironments[tests].reportPrivateUsage to "none"',
    ]);
    expect(weakerPyright({})).toEqual([
      { setting: 'typeCheckingMode', message: 'sets typeCheckingMode to "recommended"' },
    ]);
  });
});

describe('weakerComments', () => {
  it('finds file-level comments that loosen a file, not line suppressions', () => {
    const text = [
      '# pyright: basic',
      '"""Module."""',
      '# pyright: strict',
      '# pyright: reportAny=false, reportUnusedImport=true',
      'x = f()  # pyright: ignore[reportAny]',
      '# pyright: ignore',
      '#pyright: reportPrivateUsage=warning',
      '# pyright: all',
    ].join('\n');
    expect(weakerComments(text)).toEqual([
      { line: 1, directive: 'basic' },
      { line: 3, directive: 'strict' },
      { line: 4, directive: 'reportAny=false, reportUnusedImport=true' },
      { line: 7, directive: 'reportPrivateUsage=warning' },
    ]);
  });
});
